import bpy

target=bpy.data.scenes.get('SALVADOR | ESBOCO OFICIAL')
if target is None:
    raise RuntimeError('Target scene SALVADOR | ESBOCO OFICIAL not found')
wm=bpy.context.window_manager
count=0
for w in wm.windows:
    w.scene=target
    count+=1
coll=bpy.data.collections.get('Lacerda_Upper_Blockout')
if coll:
    for o in bpy.context.selected_objects:
        o.select_set(False)
    for o in coll.objects:
        if o.name in target.objects:
            o.hide_set(False)
            o.hide_viewport=False
            o.select_set(True)
    active=next((o for o in coll.objects if o.name in target.objects), None)
    if active:
        target.view_layers[0].objects.active=active
# Frame all 3D views in all windows
framed=0
for w in wm.windows:
    try:
        for area in w.screen.areas:
            if area.type=='VIEW_3D':
                region=next((r for r in area.regions if r.type=='WINDOW'), None)
                if region:
                    with bpy.context.temp_override(window=w, screen=w.screen, area=area, region=region, scene=target):
                        bpy.ops.view3d.view_selected(use_all_regions=False)
                    framed+=1
    except Exception:
        pass
print(f'Switched {count} window(s) to scene {target.name}; framed {framed} VIEW_3D area(s); scene_objects={len(target.objects)}')
